import inspect
from fastapi.dependencies.models import Dependency
from fastapi import FastAPI

async def iscoroutinefunction(func):
    return inspect.iscoroutinefunction(func)

def isgeneratorfunction(func):
    return inspect.isgeneratorfunction(func)

def isasyncgenfunction(func):
    return inspect.isasyncgenfunction(func)

class CoroClass:
    async def __call__(self):
        yield 1

class GenClass:
    def __call__(self):
        yield 1

class AsyncGenClass:
    async def __call__(self):
        yield 1

def test_coro_class():
    dep = Dependency(call=CoroClass)
    assert dep.is_coroutine_callable is False, f"CoroClass should not be coroutine_callable, got {dep.is_coroutine_callable}"

def test_gen_class():
    dep = Dependency(call=GenClass)
    assert dep.is_gen_callable is False, f"GenClass should not be gen_callable, got {dep.is_gen_callable}"

def test_async_gen_class():
    dep = Dependency(call=AsyncGenClass)
    assert dep.is_async_gen_callable is False, f"AsyncGenClass should not be async_gen_callable, got {dep.is_async_gen_callable}"

if __name__ == "__main__":
    try:
        test_coro_class()
        print("test_coro_class passed")
        test_gen_class()
        print("test_gen_class passed")
        test_async_gen_class()
        print("test_async_gen_class passed")
        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)

